const documentUpload=multer({storage:multer.diskStorage({destination:(_req,_file,cb)=>cb(null,documentRoot),filename:(_req,file,cb)=>cb(null,randomUUID()+path.extname(file.originalname).toLowerCase())}),limits:{fileSize:20*1024*1024,files:1},fileFilter:(_req,file,cb)=>{const ext=path.extname(file.originalname).toLowerCase(),ok=(ext==='.pdf'&&file.mimetype==='application/pdf')||(['.jpg','.jpeg'].includes(ext)&&file.mimetype==='image/jpeg')||(ext==='.png'&&file.mimetype==='image/png');cb(ok?null:new Error('Format refusé. Formats autorisés : PDF, JPG, PNG.'),ok);}});
async function validDocumentSignature(file){const h=await fsp.open(file.path,'r');try{const b=Buffer.alloc(8);await h.read(b,0,8,0);const ext=path.extname(file.originalname).toLowerCase();return ext==='.pdf'?b.subarray(0,5).toString()==='%PDF-':(['.jpg','.jpeg'].includes(ext)?b[0]===0xff&&b[1]===0xd8&&b[2]===0xff:ext==='.png'?b.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])):false);}finally{await h.close();}}
function isoDate(value){
 if(!value)return null;
 const raw=String(value).trim(),match=raw.match(/^(\d{4}-\d{2}-\d{2})$/);
 if(match)return match[1];
 const parsed=value instanceof Date?value:new Date(raw);
 if(Number.isNaN(parsed.getTime()))return null;
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Tunis',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(parsed);
 const get=k=>parts.find(x=>x.type===k)?.value||'';
 return get('year')+'-'+get('month')+'-'+get('day');
}
function addMonthsISO(value,months){if(!value)return null;const m=isoDate(value)?.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return null;const first=new Date(Number(m[1]),Number(m[2])-1,1,12);first.setMonth(first.getMonth()+Number(months||0));const last=new Date(first.getFullYear(),first.getMonth()+1,0,12).getDate();first.setDate(Math.min(Number(m[3]),last));return first.getFullYear()+'-'+String(first.getMonth()+1).padStart(2,'0')+'-'+String(first.getDate()).padStart(2,'0');}
function closeoutInfo(p){
 const legacy=p.legacy_payload||{},type=String(p.procedure_type||legacy.type_procedure||'').trim().toLowerCase();
 const isConsultation=type.includes('consult'),isMarket=type.includes('march');
 const provisional=isoDate(p.provisional_reception_date||legacy.date_reception_provisoire);
 const raw=p.warranty_months??legacy.duree_garantie_mois;
 const duration=raw==null||raw===''?(isMarket?12:0):Math.max(0,Number(raw)||0);
 const warrantyEnd=provisional&&duration>0?addMonthsISO(provisional,duration):null;
 const definitive=isoDate(p.definitive_reception_date||legacy.date_reception_definitive);
 const settlement=isoDate(isConsultation?(p.last_payment_date||p.final_payment_date||legacy.date_reglement_definitif):(p.final_payment_date||legacy.date_reglement_definitif||p.last_payment_date));
 const closure=isoDate(p.closure_date||legacy.date_cloture);
 const deadline=definitive?addMonthsISO(definitive,3):null;
 const now=new Date(),today=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');
 let status='Procédure non renseignée',code='unknown';
 if(isConsultation){
  if(settlement&&closure&&closure>=settlement){status='Clôturée définitivement · consultation';code='closed';}
  else if(settlement||closure){status='Clôture financière incomplète · consultation';code='incomplete';}
  else{status='Règlement et clôture à renseigner';code='to_close';}
 }else if(isMarket){
  if(!provisional){status='Réception provisoire à renseigner';code='missing_provisional';}
  else if(!definitive){if(warrantyEnd&&today<warrantyEnd){status='En période de garantie';code='warranty';}else{status='Réception définitive à enregistrer';code='awaiting_definitive';}}
  else if(warrantyEnd&&definitive<warrantyEnd){status='Réception définitive antérieure à la fin de garantie';code='invalid_definitive_date';}
  else if(closure&&settlement&&closure>=definitive&&closure>=settlement){status='Clôturé définitivement · marché';code='closed';}
  else if(deadline&&today>deadline&&!closure){status='Délai de clôture dépassé';code='overdue';}
  else if(closure||settlement){status='Clôture incomplète';code='incomplete';}
  else{status='À clôturer';code='to_close';}
 }else if(type){status='Type de procédure à vérifier';code='unknown';}
 return {procedure_type:type,provisional_reception_date:provisional,warranty_months:duration,definitive_reception_date:definitive,final_payment_date:settlement,closure_date:closure,warranty_end_date:warrantyEnd,closure_deadline:deadline,closure_status:status,closure_code:code,financially_closed:code==='closed'};
}
