function validateProjectGeometry(g,type){
 if(!g||typeof g!=='object'||!['Point','LineString','Polygon'].includes(type)||g.type!==type||!Array.isArray(g.coordinates))return false;
 let count=0;const validPosition=p=>Array.isArray(p)&&p.length>=2&&Number.isFinite(Number(p[0]))&&Number.isFinite(Number(p[1]))&&Math.abs(Number(p[0]))<=180&&Math.abs(Number(p[1]))<=90;
 const walk=x=>{if(!Array.isArray(x))return false;if(x.length>=2&&typeof x[0]==='number'){count++;return validPosition(x);}return x.every(walk);};
 if(!walk(g.coordinates)||count>20000)return false;
 if(type==='Point')return validPosition(g.coordinates);
 if(type==='LineString')return g.coordinates.length>=2&&g.coordinates.every(validPosition);
 if(type==='Polygon')return g.coordinates.length>0&&g.coordinates.every(r=>r.length>=4&&r.every(validPosition)&&JSON.stringify(r[0])===JSON.stringify(r[r.length-1]));
 return false;
}
const gisSymbols=['monument','building','school','sport','health','water','road','other'];
function normalizeGisProperties(value){const p=value&&typeof value==='object'?value:{};return {symbol:gisSymbols.includes(p.symbol)?p.symbol:'other',color:/^#[0-9a-fA-F]{6}$/.test(String(p.color||''))?String(p.color):'#64748b'};}
app.get('/api/geometries',authRequired,async(_req,res)=>{try{const q=await pool.query("SELECT g.id,g.project_id,g.geometry_type,g.geometry,g.label,g.description,g.properties,g.created_at,g.updated_at,p.project_code,p.title AS project_title FROM project_geometries g JOIN projects p ON p.id=g.project_id ORDER BY g.updated_at DESC,g.id DESC");res.json({items:q.rows});}catch(e){console.error('Chargement SIG impossible:',e);res.status(500).json({error:'Impossible de charger les objets géographiques.'});}});
app.post('/api/projects/:id/geometries',authRequired,allow('admin','technical'),async(req,res)=>{const b=req.body||{},type=String(b.geometry_type||b.geometry?.type||'');if(!String(b.label||'').trim()||String(b.label).trim().length>200||!validateProjectGeometry(b.geometry,type))return res.status(400).json({error:'Objet géographique invalide : vérifiez le nom, le type et les coordonnées.'});const c=await pool.connect();try{await c.query('BEGIN');const p=await c.query('SELECT id,project_code,title FROM projects WHERE id::text=$1 OR project_code=$1 FOR UPDATE',[req.params.id]);if(!p.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Projet introuvable.'});}const props=normalizeGisProperties(b.properties);const q=await c.query('INSERT INTO project_geometries(project_id,geometry_type,geometry,label,description,properties,created_by,updated_by) VALUES($1,$2,$3::jsonb,$4,$5,$6::jsonb,$7,$7) RETURNING *',[p.rows[0].id,type,JSON.stringify(b.geometry),String(b.label).trim(),String(b.description||''),JSON.stringify(props),req.user.id]);await c.query("INSERT INTO project_history(project_id,user_id,event_type,summary,after_data) VALUES($1,$2,'geometry_created',$3,$4)",[p.rows[0].id,req.user.id,'Objet SIG créé : '+String(b.label).trim()+' ('+type+')',JSON.stringify({label:String(b.label).trim(),geometry_type:type,properties:props})]);await c.query('COMMIT');res.status(201).json({...q.rows[0],project_code:p.rows[0].project_code,project_title:p.rows[0].title});}catch(e){await c.query('ROLLBACK');console.error('Création objet SIG impossible:',e);res.status(500).json({error:e.code==='42P01'?'Table project_geometries absente : exécutez schema-gis.sql.':'Enregistrement SIG impossible. Consultez le journal du serveur.'});}finally{c.release();}});
app.put('/api/geometries/:id',authRequired,allow('admin','technical'),async(req,res)=>{const b=req.body||{},c=await pool.connect();try{await c.query('BEGIN');const old=await c.query('SELECT g.*,p.project_code,p.title AS project_title FROM project_geometries g JOIN projects p ON p.id=g.project_id WHERE g.id=$1 FOR UPDATE',[req.params.id]);if(!old.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Objet géographique introuvable.'});}const type=String(b.geometry_type||b.geometry?.type||old.rows[0].geometry_type),geometry=b.geometry||old.rows[0].geometry,label=String(b.label??old.rows[0].label).trim(),description=String(b.description??old.rows[0].description??''),properties=normalizeGisProperties(b.properties??old.rows[0].properties);if(!label||label.length>200||!validateProjectGeometry(geometry,type)){await c.query('ROLLBACK');return res.status(400).json({error:'Données géographiques invalides.'});}const q=await c.query('UPDATE project_geometries SET geometry_type=$1,geometry=$2::jsonb,label=$3,description=$4,properties=$5::jsonb,updated_by=$6,updated_at=now() WHERE id=$7 RETURNING *',[type,JSON.stringify(geometry),label,description,JSON.stringify(properties),req.user.id,req.params.id]);await c.query("INSERT INTO project_history(project_id,user_id,event_type,summary,before_data,after_data) VALUES($1,$2,'geometry_updated',$3,$4,$5)",[old.rows[0].project_id,req.user.id,'Objet SIG modifié : '+old.rows[0].label+' → '+label,JSON.stringify({label:old.rows[0].label,geometry_type:old.rows[0].geometry_type,properties:old.rows[0].properties}),JSON.stringify({label,geometry_type:type,properties})]);await c.query('COMMIT');res.json({...q.rows[0],project_code:old.rows[0].project_code,project_title:old.rows[0].project_title});}catch(e){await c.query('ROLLBACK');console.error('Modification objet SIG impossible:',e);res.status(500).json({error:'Modification SIG impossible.'});}finally{c.release();}});
app.delete('/api/geometries/:id',authRequired,allow('admin','technical'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const old=await c.query('DELETE FROM project_geometries WHERE id=$1 RETURNING *',[req.params.id]);if(!old.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Objet géographique introuvable.'});}await c.query("INSERT INTO project_history(project_id,user_id,event_type,summary,before_data) VALUES($1,$2,'geometry_deleted',$3,$4)",[old.rows[0].project_id,req.user.id,'Objet SIG supprimé : '+old.rows[0].label,JSON.stringify({label:old.rows[0].label,geometry_type:old.rows[0].geometry_type,properties:old.rows[0].properties})]);await c.query('COMMIT');res.json({ok:true});}catch(e){await c.query('ROLLBACK');console.error('Suppression objet SIG impossible:',e);res.status(500).json({error:'Suppression SIG impossible.'});}finally{c.release();}});

app.get('/api/documents',authRequired,async(req,res)=>{
 try{
  const {year,category,subcategory,document_type,project}=req.query;
  const values=[req.user.role];
  const where=["($1 IN ('admin','viewer') OR d.section=$1)"];
  for(const [column,value] of [['p.initial_programming_year',year],['p.category',category],['p.subcategory',subcategory],['d.document_type',document_type]]){
   if(value!==undefined&&String(value).trim()!==''){
    values.push(String(value).trim());
    where.push(column+'=$'+values.length);
   }
  }
  if(project&&String(project).trim()){values.push('%'+String(project).trim().replace(/[\\%_]/g,'\\$&')+'%');where.push('(p.title ILIKE $'+values.length+' OR p.project_code ILIKE $'+values.length+')');}
  const sql=`SELECT d.id,d.project_id,d.section,d.document_type,d.title,d.reference_number,d.document_date,d.original_filename,d.mime_type,d.file_size,d.created_at,d.uploaded_by,u.display_name AS uploaded_by,p.project_code,p.title AS project_title,p.initial_programming_year,p.category,p.subcategory
   FROM project_documents d
   JOIN projects p ON p.id=d.project_id
   LEFT JOIN app_users u ON u.id=d.uploaded_by
   WHERE ${where.join(' AND ')}
   ORDER BY d.document_date DESC NULLS LAST,d.created_at DESC,d.id DESC`;
  const q=await pool.query(sql,values);
  res.json({items:q.rows});
 }catch(e){
  console.error('Chargement des documents impossible:',e);
  res.status(500).json({error:'Impossible de charger les documents.'});
 }
});
const settingGroups=new Set(['project_category','project_subcategory','procedure_type','document_type_technical','document_type_finance','technical_stage','operational_status','gis_symbol']);
app.get('/api/settings',authRequired,async(req,res)=>{try{const includeInactive=req.user.role==='admin'&&req.query.include_inactive==='1';const q=await pool.query("SELECT s.id,s.group_key,s.code,s.label_fr,s.label_ar,s.parent_id,p.code parent_code,s.metadata,s.sort_order,s.is_active,s.is_system,s.updated_at FROM app_settings s LEFT JOIN app_settings p ON p.id=s.parent_id WHERE ($1::boolean OR s.is_active=true) ORDER BY s.group_key,s.sort_order,s.label_fr",[includeInactive]);res.json({items:q.rows});}catch(e){console.error('Lecture paramètres impossible:',e);res.status(500).json({error:'Impossible de charger les paramètres.'});}});
app.post('/api/settings',authRequired,allow('admin'),async(req,res)=>{const b=req.body||{},group=String(b.group_key||''),code=String(b.code||'').trim(),label=String(b.label_fr||'').trim();if(!settingGroups.has(group)||group==='operational_status'||!code||code.length>160||!label||label.length>160)return res.status(400).json({error:'Groupe, code ou libellé invalide. Les états opérationnels sont des codes système.'});const c=await pool.connect();try{await c.query('BEGIN');let parentId=null;if(group==='project_subcategory'){const p=await c.query("SELECT id FROM app_settings WHERE group_key='project_category' AND code=$1 AND is_active=true",[String(b.parent_code||'')]);if(!p.rowCount)throw Object.assign(new Error('Sélectionnez une catégorie parente active.'),{status:400});parentId=p.rows[0].id;}const q=await c.query('INSERT INTO app_settings(group_key,code,label_fr,label_ar,parent_id,sort_order,is_active,created_by,updated_by) VALUES($1,$2,$3,$4,$5,$6,true,$7,$7) RETURNING *',[group,code,label,String(b.label_ar||'').trim()||null,parentId,Number.isInteger(Number(b.sort_order))?Number(b.sort_order):0,req.user.id]);await c.query("INSERT INTO app_settings_history(setting_id,group_key,code,action,after_data,user_id) VALUES($1,$2,$3,'created',$4,$5)",[q.rows[0].id,group,code,JSON.stringify(q.rows[0]),req.user.id]);await c.query('COMMIT');res.status(201).json(q.rows[0]);}catch(e){await c.query('ROLLBACK');console.error('Création paramètre impossible:',e);res.status(e.status|| (e.code==='23505'?409:500)).json({error:e.status?e.message:e.code==='23505'?'Ce code existe déjà dans cette rubrique.':'Création du paramètre impossible.'});}finally{c.release();}});
app.put('/api/settings/:id',authRequired,allow('admin'),async(req,res)=>{const b=req.body||{},label=String(b.label_fr||'').trim();if(!label||label.length>160)return res.status(400).json({error:'Le libellé français est obligatoire (160 caractères maximum).'});const c=await pool.connect();try{await c.query('BEGIN');const old=await c.query('SELECT * FROM app_settings WHERE id=$1 FOR UPDATE',[req.params.id]);if(!old.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Paramètre introuvable.'});}const current=old.rows[0];let parentId=current.parent_id;if(current.group_key==='project_subcategory'&&b.parent_code!==undefined){const p=await c.query("SELECT id FROM app_settings WHERE group_key='project_category' AND code=$1 AND is_active=true",[String(b.parent_code||'')]);if(!p.rowCount)throw Object.assign(new Error('Sélectionnez une catégorie parente active.'),{status:400});parentId=p.rows[0].id;}const q=await c.query('UPDATE app_settings SET label_fr=$1,label_ar=$2,parent_id=$3,sort_order=$4,updated_by=$5,updated_at=now() WHERE id=$6 RETURNING *',[label,String(b.label_ar||'').trim()||null,parentId,Number.isInteger(Number(b.sort_order))?Number(b.sort_order):current.sort_order,req.user.id,current.id]);await c.query("INSERT INTO app_settings_history(setting_id,group_key,code,action,before_data,after_data,user_id) VALUES($1,$2,$3,'updated',$4,$5,$6)",[current.id,current.group_key,current.code,JSON.stringify(current),JSON.stringify(q.rows[0]),req.user.id]);await c.query('COMMIT');res.json(q.rows[0]);}catch(e){await c.query('ROLLBACK');console.error('Modification paramètre impossible:',e);res.status(e.status||500).json({error:e.status?e.message:'Modification du paramètre impossible.'});}finally{c.release();}});
app.patch('/api/settings/:id/active',authRequired,allow('admin'),async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const old=await c.query('SELECT * FROM app_settings WHERE id=$1 FOR UPDATE',[req.params.id]);if(!old.rowCount){await c.query('ROLLBACK');return res.status(404).json({error:'Paramètre introuvable.'});}const current=old.rows[0],active=Boolean(req.body&&req.body.is_active);if(current.is_system&&['operational_status'].includes(current.group_key)&&!active){await c.query('ROLLBACK');return res.status(400).json({error:'Les états opérationnels système ne peuvent pas être désactivés.'});}if(current.group_key==='project_category'&&!active){const children=await c.query('SELECT 1 FROM app_settings WHERE parent_id=$1 AND is_active=true LIMIT 1',[current.id]);if(children.rowCount){await c.query('ROLLBACK');return res.status(409).json({error:'Désactivez d’abord les sous-catégories de cette catégorie.'});}}const q=await c.query('UPDATE app_settings SET is_active=$1,updated_by=$2,updated_at=now() WHERE id=$3 RETURNING *',[active,req.user.id,current.id]);await c.query("INSERT INTO app_settings_history(setting_id,group_key,code,action,before_data,after_data,user_id) VALUES($1,$2,$3,$4,$5,$6,$7)",[current.id,current.group_key,current.code,active?'activated':'deactivated',JSON.stringify(current),JSON.stringify(q.rows[0]),req.user.id]);await c.query('COMMIT');res.json(q.rows[0]);}catch(e){await c.query('ROLLBACK');console.error('Activation paramètre impossible:',e);res.status(e.status||500).json({error:e.status?e.message:'Modification du statut impossible.'});}finally{c.release();}});
app.get('/api/settings/history',authRequired,allow('admin'),async(_req,res)=>{try{const q=await pool.query('SELECT h.*,u.display_name FROM app_settings_history h LEFT JOIN app_users u ON u.id=h.user_id ORDER BY h.created_at DESC LIMIT 300');res.json({items:q.rows});}catch(e){console.error(e);res.status(500).json({error:'Impossible de charger l’historique des paramètres.'});}});
app.get('/api/users',authRequired,allow('admin'),async(_req,res)=>{try{const q=await pool.query('SELECT id,username,display_name,role,is_active,created_at FROM app_users ORDER BY display_name,username');res.json({items:q.rows});}catch(e){console.error('Lecture utilisateurs impossible:',e);res.status(500).json({error:'Impossible de charger les utilisateurs.'});}});
app.post('/api/users',authRequired,allow('admin'),async(req,res)=>{const {username,display_name,password,role}=req.body||{};if(!username||!display_name||!password||!['admin','technical','finance','viewer'].includes(role)||String(password).length<12)return res.status(400).json({error:'Données invalides. Mot de passe : 12 caractères minimum.'});try{const hash=await bcrypt.hash(password,12);const q=await pool.query('INSERT INTO app_users(username,display_name,password_hash,role) VALUES($1,$2,$3,$4) RETURNING id,username,display_name,role,is_active',[username,display_name,hash,role]);res.status(201).json(q.rows[0]);}catch(e){console.error('Création utilisateur impossible:',{code:e.code,message:e.message,detail:e.detail,constraint:e.constraint});res.status(e.code==='23505'?409:500).json({error:e.code==='23505'?'Identifiant déjà utilisé.':'Création utilisateur impossible. Consultez le journal du serveur pour le détail.'});}});
app.get('/api/meeting-responsibles',authRequired,async(_req,res)=>{try{const q=await pool.query("SELECT pr.project_id,u.display_name FROM project_responsibilities pr JOIN app_users u ON u.id=pr.user_id WHERE pr.active=TRUE AND pr.responsibility_role='principal'");res.json({items:q.rows});}catch(e){console.error(e);res.status(500).json({error:'Impossible de charger les responsables principaux.'});}});
app.get('/api/report-history',authRequired,async(_req,res)=>{try{const q=await pool.query('SELECT f.project_id,p.project_code,p.title,f.followup_date,f.physical_progress,f.operational_status,f.current_stage,f.blockage_reason,f.corrective_action,f.planned_resumption_date,f.observations FROM project_followups f JOIN projects p ON p.id=f.project_id ORDER BY f.followup_date ASC,f.id ASC');res.json({items:q.rows});}catch(e){console.error('Chargement historique des rapports impossible:',e);res.status(500).json({error:'Impossible de charger l’historique des suivis.'});}});
app.get('/api/audit',authRequired,allow('admin'),async(_req,res)=>{const q=await pool.query('SELECT a.*,u.display_name FROM audit_logs a LEFT JOIN app_users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 200');res.json({items:q.rows});});
